    o.append(P(bk, '확3-3', '<span class="tag">과학적 사고력</span>생식세포의 염색체 수가 모세포에 비해 절반인 까닭을 감수 분열과 관련지어 설명해 보자.', lines=2,
               ans='서술형', exp='감수 1분열에서 상동 염색체가 분리되어 서로 다른 딸세포로 들어가고, 감수 2분열 전에 DNA 복제가 일어나지 않기 때문이다.'))
    o.append(P(bk, '해3', '<b>[해 보기] 발생 과정 표현하기</b> — 고무찰흙으로 발생 과정 모형을 만들었다. 난할이 일반적인 체세포 분열과 다른 점은 무엇인가?', lines=2,
               ans='서술형', exp='분열 후 딸세포가 자라지 않고 빠르게 분열을 반복하므로, 세포 수는 늘지만 세포 하나의 크기는 점점 작아진다.'))
    o.append(P(bk, '확4-1', '수정란은 ( 체세포, 생식세포 )와 염색체 수가 같다.', ans='체세포', exp=''))
    o.append(P(bk, '확4-2', '수정란에서 초기에 빠르게 일어나는 세포 분열을 (　　　)이라고 한다.', ans='난할', exp=''))
    o.append(P(bk, '확4-3', '<span class="tag">과학적 사고력</span>수정란이 개체로 되는 과정에서 세포 수와 세포의 종류는 어떻게 변하는지 설명해 보자.', lines=2,
               ans='서술형', exp='세포 분열로 세포 수가 늘어나고, 세포들이 여러 종류로 분화하여 조직과 기관을 이루므로 세포의 종류가 다양해진다.'))
    o.append('</div>')

    bk.set_group('교과서 · 스스로 정리하기')
