    o.append(P(bk, '정1', '세포 분열과 염색체에 대한 설명으로 옳은 것은 ○, 옳지 않은 것은 ×로 표시하시오.',
               extra='<div class="given">(1) 세포 분열은 1개의 세포가 2개로 나누어지는 것이다.<br>(2) 세포가 커지면 표면적/부피 값이 커진다.<br>(3) 세포 분열이 일어날 때 염색체는 실처럼 가늘게 풀어진다.</div>', ans='(1)○ (2)× (3)×', exp=''))
    o.append(P(bk, '정2', '체세포 분열에 대한 설명은 "체", 감수 분열에 대한 설명은 "감"이라고 쓰시오.',
               extra='<div class="given">(1) 4개의 딸세포가 만들어진다.<br>(2) 세포 분열이 1회만 일어난다.<br>(3) 모세포와 딸세포에 들어 있는 염색체 수가 같다.<br>(4) 상동 염색체가 결합했다가 나누어져 서로 다른 딸세포로 들어간다.</div>', ans='(1)감 (2)체 (3)체 (4)감', exp=''))
    o.append(P(bk, '정3', '난할에 대한 설명으로 옳은 것을 보기에서 모두 고르시오.', box=['체세포 분열에 해당한다.', '난할이 진행될수록 세포의 크기가 점점 커진다.', '난할로 만들어진 세포는 체세포와 염색체 수가 같다.'], ans='ㄱ, ㄷ', exp=''))
