    o.append(P(bk, '점❶', '다세포 생물은 세포 분열로 (　　　)를 늘려 생장한다.', ans='세포 수', exp=''))
    o.append(P(bk, '점❷', 'DNA에 담긴 각각의 유전 정보를 (　　　)라고 한다.', ans='유전자', exp=''))
    o.append(P(bk, '점❸', '체세포 1개가 2개로 나누어지는 것을 (　　　)이라고 한다.', ans='체세포 분열', exp=''))
    o.append(P(bk, '점❹', '1개의 모세포가 감수 분열을 거치면 딸세포 (　　　)개가 만들어진다.', ans='4', exp=''))
    o.append(P(bk, '점❺', '수정란이 세포 분열을 하면서 여러 과정을 거쳐 개체가 되는 것을 (　　　)이라고 한다.', ans='발생', exp=''))
    o.append(P(bk, '01', '염색체에 대한 설명으로 옳은 것을 보기에서 모두 고른 것은?', box=['염색체를 이루는 유전 물질은 DNA이다.', '세포 분열이 일어날 때 염색체를 관찰할 수 없다.', '한 염색체를 이루는 두 가닥의 염색 분체는 서로 같은 유전 정보를 지닌다.'],
               ch=['ㄱ', 'ㄴ', 'ㄷ', 'ㄱ, ㄷ', 'ㄴ, ㄷ'], ans='④', exp=''))
    o.append(P(bk, '02', '체세포 분열과 감수 분열에 대한 설명으로 옳은 것은?', ch=['세포 분열은 모두 1회만 일어난다.', '다세포 생물은 감수 분열을 통해 생장한다.', '생식세포는 염색체 수가 체세포의 절반이다.', '양파 뿌리의 생장점에서 감수 분열을 관찰할 수 있다.', '체세포 분열이 일어날 때 상동 염색체가 서로 결합했다가 분리된다.'], cols=1,
               ans='③', exp=''))
    o.append(P(bk, '05', '<span class="tag">과학적 사고력</span>세포 분열이 필요한 까닭을 세포의 부피와 표면적의 관계 및 세포 표면에서 일어나는 물질 교환과 관련지어 설명하시오.', lines=3,
               ans='서술형', exp='세포가 커지면 부피에 비해 표면적이 상대적으로 작아져(표면적/부피 감소) 세포 표면을 통한 물질 교환이 불리해진다. 따라서 어느 정도 커지면 분열하여 수를 늘린다.'))
    o.append(P(bk, '06', '<span class="tag">과학적 사고력</span>수정란에서 난할이 진행될 때의 특징을 딸세포의 수와 크기, 딸세포에 들어 있는 염색체 수와 관련지어 설명하시오.', lines=3,
               ans='서술형', exp='딸세포의 수는 늘어나지만 세포가 자라지 않고 분열하므로 크기는 점점 작아진다. 체세포 분열이므로 딸세포의 염색체 수는 수정란과 같다.'))
    o.append('</div>')
    return '\n'.join(o)


